#include <Arduino.h>
#include <TM1637Display.h>
#include <string.h>

TM1637Display display(4,5);
const int lightThreshold=400;
bool manualArmed=false;
bool alarmOn=false;
bool previousCondition=false;
unsigned long events=0;
char command[32];
unsigned int used=0;
unsigned long lastByte=0;

bool nightMode(){ return analogRead(A0)<lightThreshold; }
void executeCommand(){
  command[used]='\0';
  if(strcmp(command,"ARM")==0){ manualArmed=true; }
  else if(strcmp(command,"DISARM")==0){
    manualArmed=false;
    alarmOn=false;
    previousCondition=false;
    noTone(6);
    digitalWrite(13,LOW);
  }
  else if(strcmp(command,"RESET")==0){
    events=0;
    display.showNumberDec(0);
  }
  else if(strcmp(command,"STATUS")==0){
    Serial.print("Mode: ");
    Serial.print(manualArmed ? "ARMED" : (nightMode() ? "NIGHT" : "DISARMED"));
    Serial.print(" Alarm: "); Serial.print(alarmOn ? 1 : 0);
    Serial.print(" Events: "); Serial.println(events);
  }
  used=0;
}
void setup(){
  pinMode(2,INPUT);
  pinMode(3,INPUT_PULLUP);
  pinMode(6,OUTPUT);
  pinMode(13,OUTPUT);
  digitalWrite(13,LOW);
  noTone(6);
  Serial.begin(9600);
  display.setBrightness(7);
  display.showNumberDec(0);
}
void loop(){
  while(Serial.available()){
    char c=(char)Serial.read();
    lastByte=millis();
    if(c=='\n' || c=='\r'){
      if(used) executeCommand();
    } else if(used<sizeof(command)-1){ command[used++]=c; }
  }
  if(used && millis()-lastByte>=20) executeCommand();
  bool armed=manualArmed || nightMode();
  bool condition=armed && digitalRead(3)==HIGH && digitalRead(2)==HIGH;
  if(condition && !previousCondition){
    ++events;
    display.showNumberDec((int)(events%10000));
  }
  previousCondition=condition;
  if(condition!=alarmOn){
    alarmOn=condition;
    digitalWrite(13,alarmOn ? HIGH : LOW);
    if(alarmOn) tone(6,2000); else noTone(6);
  }
}
